def sum_of_two_integers(a, b):
    if b >= 0:
        for _ in range(b):
            a += 1                # step a up, one at a time, to simulate addition
    else:
        for _ in range(-b):
            a -= 1                # step a down, one at a time, for a negative b
    return a


if __name__ == "__main__":
    a, b = 5, 3
    print(sum_of_two_integers(a, b))

