import java.util.*;

public class Main {
    int sumOfTwoIntegers(int a, int b) {
        if (b >= 0) {
            for (int i = 0; i < b; i++) {
                a += 1;                  // step a up, one at a time, to simulate addition
            }
        } else {
            for (int i = 0; i < -b; i++) {
                a -= 1;                  // step a down, one at a time, for a negative b
            }
        }
        return a;
    }

    public static void main(String[] args) {
        int a = 5, b = 3;
        Main solution = new Main();
        System.out.println(solution.sumOfTwoIntegers(a, b));
    }
}

