def sum_of_two_integers(a, b):
    while b != 0:
        carry = a & b               # bits where both a and b are 1 produce a carry
        a = a ^ b                    # bits that differ combine without carrying
        b = carry << 1               # the carry moves one position to the left
    return a                       # once there is no carry left, a holds the final sum


if __name__ == "__main__":
    a, b = 5, 3
    print(sum_of_two_integers(a, b))

